sys_script_include.script:
function InstanceDeactivateAI()
{
	if (IsUserMaint() == false)
	{
		LogError('InstanceDeactivateAI requires "maint" access');
		return false;
	}

	Log('InstanceDeactivateAI STARTS');



	var aLLMServices = ['LLMGateway','LLMProxy','MLPredictor-Triton'];
	var strEncodedQuery = 'nameIN' + GetStringValue(aLLMServices);

	var aServicesSysIds = [];
	var grSS = new GlideRecord('sys_service');
	grSS.addEncodedQuery(strEncodedQuery);
	grSS.query();
	while (grSS.next() == true)
	{
		aServicesSysIds.push(GetStringValue(grSS.sys_id));
	}

	var grSSE = new GlideRecord('sys_service_endpoint');
	grSSE.addQuery('service','IN',GetStringValue(aServicesSysIds));
	grSSE.query();
	while (grSSE.next())
	{
		grSSE.url = '';
		//grSEE.update();
		Log(grSEE);

	}

	/*

	/now/nav/ui/classic/params/target/http_connection.do%3Fsys_id%3D8c655428777721105de60f207b5a9994
/now/nav/ui/classic/params/target/sys_service_list.do%3F%26sysparm_query%3DnameINLLMGateway%252CLLMProxy%252CMLPredictor-Triton
/now/nav/ui/classic/params/target/sys_one_extend_capability_definition_list.do%3Fsysparm_query%3Dadvanced%253Dtrue%26sysparm_first_row%3D1%26sysparm_view%3D

	 */

	var installer = new InstallerAPI('InstanceDeactivateAI');

	return installer.Finish();
}
